// === ESTRUCTURA DEL PATRÓN ABSTRACT FACTORY ===

// 1. Interfaces de Producto
interface Button {
  render(): void;
  onClick(handler: () => void): void;
}

interface Checkbox {
  render(): void;
  toggle(): void;
}

// 2. Productos Concretos — Windows
class WinButton implements Button {
  render() { console.log('Botón Windows'); }
  onClick(handler: () => void) { /* Win event */ }
}

class WinCheckbox implements Checkbox {
  render() { console.log('Checkbox Windows'); }
  toggle() { /* Win toggle */ }
}

// 3. Productos Concretos — Mac
class MacButton implements Button {
  render() { console.log('Botón macOS'); }
  onClick(handler: () => void) { /* Mac event */ }
}

class MacCheckbox implements Checkbox {
  render() { console.log('Checkbox macOS'); }
  toggle() { /* Mac toggle */ }
}

// 4. Interfaz Abstract Factory
interface GUIFactory {
  createButton(): Button;
  createCheckbox(): Checkbox;
}

// 5. Fábricas Concretas
class WinFactory implements GUIFactory {
  createButton(): Button { return new WinButton(); }
  createCheckbox(): Checkbox { return new WinCheckbox(); }
}

class MacFactory implements GUIFactory {
  createButton(): Button { return new MacButton(); }
  createCheckbox(): Checkbox { return new MacCheckbox(); }
}

// 6. Cliente — solo conoce interfaces
function buildUI(factory: GUIFactory) {
  const button = factory.createButton();
  const checkbox = factory.createCheckbox();
  button.render();
  checkbox.render();
}

// Uso:
const os = detectOS();
const factory = os === 'win' ? new WinFactory() : new MacFactory();
buildUI(factory);

